#### From mathcomp Require Import all_ssreflect all_algebra. From mathcomp Require Import reals geometry trigo. Set Implicit Arguments. Unset Strict Implicit. Unset Printing Implicit Defensive. Local Open Scope ring_scope. Variable R : realType. Theorem putnam_2020_b5_skaters_meeting_distance : let A := (0, 0) : R * R in let B := (100, 0) : R * R in let vA := 8 : R in let vB := 7 : R in let theta := PI / 3 in let posA (t : R) := (vA * t * cos theta, vA * t * sin theta) in exists t0 dirB, 0 < t0 /\ normr (posA t0 - (B.1 + vB * t0 * cos dirB, B.2 + vB * t0 * sin dirB)) = 0 /\ (forall t dir, 0 < t -> normr (posA t - (B.1 + vB * t * cos dir, B.2 + vB * t * sin dir)) >= normr (posA t0 - (B.1 + vB * t0 * cos dirB, B.2 + vB * t0 * sin dirB))).
